def func(a, b=5, c=10):
    print(a, b, c)

func(2, c=20)

❓ Question: What will be the output of the following Python code?

def add(*args):
    return sum(args)

print(add(10, 20, 30))

❓ Question: What will be the output of the following Python code?

class Animal:
    def sound(self):
        print("Animal Sound")

class Dog(Animal):
    def sound(self):
        print("Bark")

obj = Dog()
obj.sound()

❓ Question: What will be the output of the following Python code?

def decorator(func):
    def wrapper():
        print("Before Function")
        func()
        print("After Function")
    return wrapper

@decorator
def greet():
    print("Hello")

greet()
